using System;using System.IO;using System.Linq;using System.Text;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEngine.SceneManagement;
[InitializeOnLoad]public static class CityMobileLODAudit{static CityMobileLODAudit(){EditorApplication.update+=Poll;}static void Poll(){if(EditorApplication.isCompiling||!File.Exists("CityMobileLODAudit.request"))return;File.Delete("CityMobileLODAudit.request");var sc=SceneManager.GetActiveScene();var lods=sc.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<LODGroup>(true)).ToArray();var s=new StringBuilder();var map=new Dictionary<Renderer,HashSet<LODGroup>>();foreach(var g in lods){int level=0;foreach(var l in g.GetLODs()){foreach(var r in l.renderers){if(!r){s.AppendLine("NULL "+AnimationUtility.CalculateTransformPath(g.transform,null)+" level="+level+" prefab="+PrefabUtility.GetPrefabAssetPathOfNearestInstanceRoot(g.gameObject));continue;}if(!map.ContainsKey(r))map[r]=new HashSet<LODGroup>();map[r].Add(g);}level++;}}foreach(var p in map.Where(p=>p.Value.Count>1))s.AppendLine("MULTI "+AnimationUtility.CalculateTransformPath(p.Key.transform,null)+" GROUPS="+string.Join("|",p.Value.Select(g=>AnimationUtility.CalculateTransformPath(g.transform,null))));foreach(var r in sc.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<MeshRenderer>(true)).Where(r=>r.name.StartsWith("Mobile LOD")&&!map.ContainsKey(r)))s.AppendLine("UNCONTROLLED "+AnimationUtility.CalculateTransformPath(r.transform,null));foreach(var g in lods){var own=g.GetComponent<MeshRenderer>();if(own&&!own.enabled&&g.gameObject.activeInHierarchy&&g.GetComponentsInChildren<MeshRenderer>(true).Any(r=>r.name.StartsWith("Mobile LOD")&&r.enabled&&r.gameObject.activeInHierarchy))s.AppendLine("DISABLED_NEAR "+AnimationUtility.CalculateTransformPath(g.transform,null));}s.AppendLine("LOD groups="+lods.Length+" multi="+map.Count(p=>p.Value.Count>1));File.WriteAllText("FinalEnvironmentRoadReview/MobileOptimization/LODAudit.txt",s.ToString());}}
